-- =============================================================
-- GENERATED by `npm run gen:writable-columns`. Do not edit.
--
-- Which roles hold which capability, derived from
-- `lib/crm/permissions.ts`. The database needs its own copy because a
-- function granted to `authenticated` is reachable through PostgREST
-- without the command runtime in front of it, and a function that only
-- checks whether a row is VISIBLE lets a viewer write through it.
--
-- Replaced wholesale rather than merged, so a capability a role loses is
-- a capability it loses here too. A seed that only ever grows is how a
-- revoked permission survives in the database.
--
-- 134 pairs.
-- =============================================================

CREATE TABLE IF NOT EXISTS command_capability_roles (
  capability TEXT NOT NULL,
  role       TEXT NOT NULL,
  PRIMARY KEY (capability, role)
);

ALTER TABLE command_capability_roles ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "command_capability_roles_read" ON command_capability_roles;
-- Readable so a check can compare it with the application. Nobody writes
-- it from the application: it is replaced wholesale by the generator.
CREATE POLICY "command_capability_roles_read" ON command_capability_roles
  FOR SELECT USING (auth.role() = 'authenticated');

-- Does the caller hold this capability? One place, so every function
-- that needs to ask gets the same answer as the application.
CREATE OR REPLACE FUNCTION command_may(p_capability TEXT)
RETURNS BOOLEAN
LANGUAGE SQL
SECURITY DEFINER
STABLE
AS $fn$
  SELECT EXISTS (
    SELECT 1 FROM command_capability_roles r
    WHERE r.capability = p_capability
      AND r.role = current_role_safe()
  )
$fn$;

REVOKE ALL ON FUNCTION command_may(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION command_may(TEXT) TO authenticated;

-- What it takes to make one of a table's rows, or get rid of one.
-- command_apply builds DELETE statements from a payload, and a payload
-- is not a permission.
CREATE TABLE IF NOT EXISTS command_entity_permissions (
  table_name TEXT NOT NULL,
  operation  TEXT NOT NULL CHECK (operation IN ('create', 'delete', 'attach')),
  capability TEXT NOT NULL,
  PRIMARY KEY (table_name, operation)
);

-- The set of operations grows. CREATE TABLE IF NOT EXISTS leaves an
-- existing table's constraint exactly as it was, so a database migrated
-- before the attach operation existed would refuse the seed below
-- rather than the seed telling it what changed.
ALTER TABLE command_entity_permissions
  DROP CONSTRAINT IF EXISTS command_entity_permissions_operation_check;
ALTER TABLE command_entity_permissions
  ADD CONSTRAINT command_entity_permissions_operation_check
  CHECK (operation IN ('create', 'delete', 'attach'));

ALTER TABLE command_entity_permissions ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "command_entity_permissions_read" ON command_entity_permissions;
CREATE POLICY "command_entity_permissions_read" ON command_entity_permissions
  FOR SELECT USING (auth.role() = 'authenticated');

-- May the caller create or delete a row of this table? A table with no
-- row here cannot be created or deleted through the command runtime at
-- all, which is the safe way round.
CREATE OR REPLACE FUNCTION command_may_lifecycle(p_table TEXT, p_operation TEXT)
RETURNS BOOLEAN
LANGUAGE SQL
SECURITY DEFINER
STABLE
AS $fn$
  SELECT EXISTS (
    SELECT 1 FROM command_entity_permissions e
    WHERE e.table_name = p_table
      AND e.operation = p_operation
      AND command_may(e.capability)
  )
$fn$;

REVOKE ALL ON FUNCTION command_may_lifecycle(TEXT, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION command_may_lifecycle(TEXT, TEXT) TO authenticated;

BEGIN;

DELETE FROM command_capability_roles;


DELETE FROM command_entity_permissions;


COMMIT;
